     "code": "class Matrix:\n    def __init__(self, data):\n        self.data = data\n        self.rows = len(data)\n        self.cols = len(data[0]) if data else 0\n    \n    def __repr__(self):\n        return '\\n'.join([' '.join(f'{x:8.2f}' for x in row) for row in self.data])\n    \n    def __add__(self, other):\n        return Matrix([[self.data[i][j] + other.data[i][j] \n                       for j in range(self.cols)] for i in range(self.rows)])\n    \n    def __mul__(self, other):\n        if isinstance(other, (int, float)):\n            return Matrix([[x * other for x in row] for row in self.data])\n        result = [[sum(self.data[i][k] * other.data[k][j] for k in range(self.cols))\n                   for j in range(other.cols)] for i in range(self.rows)]\n        return Matrix(result)\n    \n    def transpose(self):\n        return Matrix([[self.data[j][i] for j in range(self.rows)] for i in range(self.cols)])\n    \n    def determinant(self):\n        if self.rows != self.cols:\n            raise ValueError(\"Square matrix required\")\n        if self.rows == 1:\n            return self.data[0][0]\n        if self.rows == 2:\n            return self.data[0][0]*self.data[1][1] - self.data[0][1]*self.data[1][0]\n        det = 0\n        for j in range(self.cols):\n            minor = Matrix([[self.data[i][k] for k in range(self.cols) if k != j]\n                           for i in range(1, self.rows)])\n            det += ((-1)**j) * self.data[0][j] * minor.determinant()\n        return det\n\nA = Matrix([[1, 2], [3, 4]])\nB = Matrix([[5, 6], [7, 8]])\nprint(\"A + B:\"); print(A + B)\nprint(\"\\nA * B:\"); print(A * B)\nprint(f\"\\ndet(A) = {A.determinant()}\")  # -2",
